OUT=ROOT/'runs/z13_distribution_quality_20261015'
ID='z13_distribution_quality_v1'
pre=json.loads((OUT/'preflight.json').read_text(encoding='utf-8'))
assert pre['passed'] and pre['no_gpu'] and not pre['gpu_started']
